def get_grundy(n, k, memo):
    """Compute Grundy number for pile of size n with parameter k."""
    if n in memo:
        return memo[n]

    seen = set()

    # Option 1: Remove 1 cow
    if n > 0:
        seen.add(get_grundy(n - 1, k, memo))

    # Option 2: Split pile (only if even)
    if n % 2 == 0:
        x = n // 2
        if k % 2 == 1:
            seen.add(get_grundy(x, k, memo))
        # If k is even, split results in 0 Grundy value

    # Compute MEX (Minimum Excluded value)
    mex = 0
    while mex in seen:
        mex += 1

    return memo[n] = mex

