            lps[i] = length
            i += 1
        else:
            if length != 0:
                length = lps[length - 1]
            else:
                lps[i] = 0
                i += 1

    def get_next_state(state, char):
        while state > 0 and char != virus[state-1]:
            state = lps[state-1]
        if char == virus[state-1]:
            state += 1
        return state

    # dp[i][j][state] = length of LCS with virus matched state 'state'
    dp = [[[-1 for _ in range(k)] for _ in range(n + 1)] for _ in range(m + 1)]
    dp[i][j][0] = 0  # base case fix

    for i in range(1, m + 1):
        for j in range(1, n + 1):
            # Handle all states
            for state in range(k):
                if dp[i][j][state] != -1:
                    if s1[i-1] == s2[j-1]:
                        new_state = get_next_state(state, s1[i-1])
                        if new_state < k:
                            new_dp = dp[i-1][j-1][state] + 1
                            if new_dp > dp[i][j][new_state]:
                                dp[i][j][new_state] = new_dp

    # Find best final state
    max_len = 0
    best_state = 0
    for state in range(k):
        if dp[m][n][state] > max_len:
            max_len = dp[m][n][state]
            best_state = state

    if max_len == 0:
        return "0"

    # Reconstruct
    result = []
    i, j, state = m, n, best_state
    while i > 0 and j > 0:
        new_state = get_next_state(state, s1[i-1])
        if new_state == state and dp[i-1][j-1][state] + 1 == dp[i][j][state]:
            result.append(s1[i-1])
