def is_bitonic(arr):
    """Check if array goes up then down (bitonic)"""
    n = len(arr)
    if n <= 1:
        return True
    # Bitonic: there exists a peak where elements go up then down
    peak_found = 0
    for i in range(1, n):
        if arr[i] > arr[i-1]:
            peak_found = i
        else:
            if i > peak_found:
                return False
    return True

