    choices = [''] * n

    # Base case: before any game, balance is 0
    dp[0][OFFSET] = True

    for i in range(n):
        current_char = s[i]
        for bal in range(MAX_BALANCE):
            if not dp[i][bal]:
                continue

            real_balance = bal - OFFSET

            # Check constraints for current position (except last position)
            if i < n - 1:
                # Before final hand, balance cannot reach k or -k
                if abs(real_balance) == k:
                    continue
                # Also cannot reach k+1 since next will be invalid
                if abs(real_balance + 1) == k and current_char in ('W', '?'):
                    # Actually check what choices are valid below
                    pass
            else:
                # At final position, score must reach exactly k or -k
                if abs(real_balance) != k:
                    continue

            # Try all possible choices for '?'
            possible_choices = []
            if current_char == 'W':
                possible_choices = ['W']
            elif current_char == 'L':
                possible_choices.append('L')
                if current_char != '?' or current_char == 'L':
                    possible_choices = ['L']
            elif current_char == 'D':
                possible_choices = ['D']
            else:  # '?'
                possible_choices = ['W', 'L', 'D']

            for choice in possible_choices:
                if choice == 'W':
                    eff = 1
                elif choice == 'L':
                    eff = -1
                else:
                    eff = 0

                if i < n - 1 and abs(real_balance + eff) == k:
                    # Can't reach k before final
                    continue
                if i == n - 1 and abs(real_balance + eff) < k:
                    # At final, must exactly reach k
                    continue

                new_bal = real_balance + eff
                if abs(new_bal) == k and i < n - 1:
                    continue

                if abs(new_bal) == k and i == n - 1:
                    pass  # Valid final state

                dp[i + 1][new_bal + OFFSET] = True
                choices[i] = choice

    # Check if final position is reachable
    final_offset = OFFSET  # But final balance should be k or -k
    reached = False
    for bal in range(MAX_BALANCE):
        if dp[n][bal]:
            reached = True
            break

    if not reached:
        return "NO\n"

    # Reconstruct solution
    res = [''] * n
    bal = OFFSET  # Start at balance 0

    for i in range(n - 1, -1, -1):
        res[i] = choices[i]
        choice = res[i]
        if choice == 'W':
            bal -= 1
        elif choice == 'L':
            bal += 1
        # D doesn't change balance

