        dist = [-1] * (n + 1)
        dist[start] = 0
        q = deque([start])
        while q:
            u = q.popleft()
            for v in adj[u]:
                if dist[v] == -1:
                    dist[v] = dist[u] + 1
                    q.append(v)
        return dist

    def get_path(start, end):
        parent = {}
        q = deque([start])
        parent[start] = None
        while q:
            u = q.popleft()
            if u == end:
                break
            for v in adj[u]:
                if v not in parent:
                    parent[v] = u
                    q.append(v)
        path = []
        cur = end
        while cur is not None:
            path.append(cur)
            cur = parent[cur]
        return path[::-1]

    def path_contains(path1, x, y):
        return x in path1 or y in path1

    def path_count(path1, path2):
        return len(set(path1) & set(path2))

    max_common = -1
    max_len = -1
    best_pair1 = None
    best_pair2 = None

