def solution(input_str):
    n, k = map(int, input_str.split())
    MOD = 998244353

    if k > n:
        return "0\n"

    if k == 1:
        return str(n) + "\n"

    # dp[i] will store the count of valid divisor chains of current length ending at position i
    # Initially, for chains of length 1, each position j has 1 valid chain (just [j])
    dp = [1] * (n + 1)

    # Build up chains of increasing length
    for length in range(2, k + 1):
        new_dp = [0] * (n + 1)
        for d in range(1, n + 1):
            if dp[d] == 0:
                continue
            # For each divisor d, add its contribution to all its multiples
            # This ensures we count chains where previous element divides current element
            for j in range(d, n + 1, d):
                new_dp[j] = (new_dp[j] + dp[d]) % MOD
        dp = new_dp

    answer = sum(dp) % MOD
    return str(answer) + "\n"

